<!-- Video review lightbox: the student reviews play here, on the page. -->
<div id="ccVideoModal" class="cc-video-modal" hidden>
  <div class="cc-video-modal__backdrop" data-video-close></div>
  <div class="cc-video-modal__dialog" role="dialog" aria-modal="true" aria-label="Student video review">
    <button type="button" class="cc-video-modal__close" data-video-close aria-label="Close video">&times;</button>
    <div class="cc-video-modal__frame"></div>
  </div>
</div>

<script>
(function () {
  // The student review thumbnails are real links to youtube.com, so clicking one
  // used to leave the page and open a new tab. Play them in the lightbox instead.
  // The href stays put, so cmd/ctrl/middle-click and no-JS visitors still get
  // the YouTube page as before.
  var modal = document.getElementById('ccVideoModal');
  var frame = modal ? modal.querySelector('.cc-video-modal__frame') : null;
  if (!modal || !frame) return;

  // Handles /watch?v=ID, /shorts/ID, /embed/ID, /live/ID and youtu.be/ID.
  function videoId(href) {
    var m = /[?&]v=([\w-]{6,})/.exec(href) ||
            /(?:youtu\.be|\/shorts|\/embed|\/live)\/([\w-]{6,})/.exec(href);
    return m ? m[1] : null;
  }

  function openVideo(id, portrait) {
    // referrerpolicy is required: the server sends Referrer-Policy: same-origin,
    // which strips the Referer on cross-origin requests and makes YouTube fail
    // with error 153.
    frame.innerHTML = '<iframe src="https://www.youtube-nocookie.com/embed/' + id +
      '?autoplay=1&rel=0" title="Student video review" referrerpolicy="strict-origin-when-cross-origin"' +
      ' allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>';
    modal.classList.toggle('cc-video-modal--portrait', !!portrait);
    modal.hidden = false;
    document.body.style.overflow = 'hidden';
  }

  function closeVideo() {
    frame.innerHTML = '';
    modal.hidden = true;
    document.body.style.overflow = '';
  }

  document.querySelectorAll('.cc-videos a[data-video]').forEach(function (link) {
    link.addEventListener('click', function (e) {
      // Leave modified clicks alone so "open in new tab" keeps working.
      if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      var id = videoId(link.getAttribute('href') || '');
      if (!id) return;
      e.preventDefault();
      openVideo(id, link.getAttribute('data-video') === 'short');
    });
  });

  modal.addEventListener('click', function (e) {
    if (e.target.hasAttribute('data-video-close')) closeVideo();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !modal.hidden) closeVideo();
  });
})();
</script>
<script>
(function () {
  // ---- stat count-up on scroll-into-view (final numbers stay in the HTML for no-JS / reduced motion)
  if (!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)) {
    var nums = document.querySelectorAll('.cc-stat-num');
    if (nums.length && 'IntersectionObserver' in window) {
      var ease = function (t) { return 1 - Math.pow(1 - t, 3); };
      var fmt = function (v, comma) { return comma ? Number(v.toFixed(0)).toLocaleString('en-US') : v.toFixed(0); };
      var run = function (el) {
        if (el._done) return;
        el._done = true;
        var to = parseFloat(el.getAttribute('data-cu-to'));
        var to2 = el.getAttribute('data-cu-to2') ? parseFloat(el.getAttribute('data-cu-to2')) : null;
        var sep = el.getAttribute('data-cu-sep') || '';
        var finalTxt = el.getAttribute('data-cu-final') || null;
        var suf = el.getAttribute('data-cu-suf') || '';
        var comma = el.getAttribute('data-cu-comma') === '1';
        var start = performance.now();
        var tick = function (now) {
          var p = Math.min((now - start) / 1500, 1);
          var e = ease(p);
          if (p >= 1 && finalTxt) { el.textContent = finalTxt; }
          else {
            var out = fmt(to * e, comma);
            if (to2 != null) out += sep + fmt(to2 * e, comma);
            el.textContent = out + suf;
          }
          if (p < 1) requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
      };
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) { if (en.isIntersecting) { run(en.target); io.unobserve(en.target); } });
      }, { threshold: 0.5 });
      nums.forEach(function (n) { io.observe(n); });
    }
  }

  // ---- FAQ accordion: one open at a time, +/- sign
  var btns = document.querySelectorAll('.cc-faq-btn');
  btns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var wasOpen = btn.classList.contains('is-open');
      btns.forEach(function (b) {
        b.classList.remove('is-open');
        b.querySelector('.cc-faq-sign').innerHTML = '+';
        var a = b.parentElement.querySelector('.cc-faq-a');
        if (a) a.style.display = 'none';
      });
      if (!wasOpen) {
        btn.classList.add('is-open');
        btn.querySelector('.cc-faq-sign').innerHTML = '&ndash;';
        var ans = btn.parentElement.querySelector('.cc-faq-a');
        if (ans) ans.style.display = '';
      }
    });
  });

  // ---- above-the-fold fitting from the design (hero pill / hero image / offer scroll margin)
  function fitPill() {
    var pill = document.querySelector('.cc-hero-pill');
    if (!pill) return;
    pill.style.removeProperty('font-size');
    if (window.innerWidth > 560) return;
    var fs = parseFloat(getComputedStyle(pill).fontSize);
    while (pill.scrollWidth > pill.clientWidth + 1 && fs > 10) { fs -= 0.25; pill.style.setProperty('font-size', fs + 'px', 'important'); }
  }
  function fitHero() {
    var media = document.querySelector('.cc-hero-media');
    var img = media && media.querySelector('a');
    var cta = document.querySelector('.cc-hero-cta');
    if (!media || !img || !cta) return;
    media.style.setProperty('max-width', '720px', 'important');
    var ctaBottom = cta.getBoundingClientRect().bottom + window.scrollY;
    var imgH = img.getBoundingClientRect().height;
    var overflow = ctaBottom + 20 - window.innerHeight;
    if (overflow <= 0) return;
    var col = media.parentElement.clientWidth - 40;
    var floor = window.innerWidth <= 560 ? Math.min(col, 300) : 360;
    var w = Math.max(floor, ((imgH - overflow) * 16) / 9);
    media.style.setProperty('max-width', Math.round(w) + 'px', 'important');
  }
  function fitOfferMargin() {
    var nav = document.querySelector('.cc-nav');
    var offer = document.getElementById('offer');
    if (!nav || !offer) return;
    var pad = parseFloat(getComputedStyle(offer).paddingTop) || 0;
    offer.style.scrollMarginTop = Math.round(nav.getBoundingClientRect().height - pad + 10) + 'px';
  }
  function fit() { fitPill(); fitHero(); fitOfferMargin(); }
  window.addEventListener('resize', fit);
  [0, 150, 600, 1500].forEach(function (t) { setTimeout(fit, t); });
  var heroImg = document.querySelector('.cc-hero-media img');
  if (heroImg && !heroImg.complete) heroImg.addEventListener('load', fit, { once: true });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);

  // ---- promo preview: updates the price shown. The real price and codes are
  // verified by Mastery at checkout (src/lib/course-checkout.ts COURSE_PROMOS), keep in sync.
  var PROMOS = { STEP100: { price: 399, save: 600, msg: 'STEP100 applied. You save $100. Verified at checkout.' },
                 STEP50:  { price: 249.5, save: 750.5, msg: 'STEP50 applied. 50% off. Verified at checkout.' } };
  var input = document.getElementById('s2-promo');
  var applyBtn = document.getElementById('s2-promo-apply');
  var result = document.getElementById('s2-promo-result');
  var priceEl = document.getElementById('s2-price');
  var saveEl = document.getElementById('s2-save');
  function money(n) { return '$' + (n % 1 ? n.toFixed(2) : String(n)); }
  function showPrice(code) {
    var p = PROMOS[code];
    if (priceEl) priceEl.textContent = p ? money(p.price) : '$499';
    if (saveEl) saveEl.textContent = p ? money(p.save) : '$500';
  }
  function status(code, explicit) {
    if (!result) return;
    result.className = 'cc-promo-result';
    if (!code) { result.textContent = explicit ? 'Enter a promo code.' : 'One-time payment. Any promo code is verified at checkout.'; if (explicit) result.classList.add('is-bad'); return; }
    if (PROMOS[code]) { result.textContent = PROMOS[code].msg; result.classList.add('is-ok'); }
    else { result.textContent = "That code isn't valid. Check it or clear the field to continue."; result.classList.add('is-bad'); }
  }
  if (input) {
    input.addEventListener('input', function () {
      var code = input.value.trim().toUpperCase();
      input.setCustomValidity(code && !PROMOS[code] ? 'Enter a valid promo code or clear this field.' : '');
      showPrice(code); status(code, false);
    });
    input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); applyBtn && applyBtn.click(); } });
  }
  if (applyBtn) applyBtn.addEventListener('click', function () {
    var code = (input.value || '').trim().toUpperCase();
    input.value = code; showPrice(code); status(code, true);
  });
  var form = document.getElementById('s2-checkout');
  if (form) form.addEventListener('submit', function () { input.value = input.value.trim().toUpperCase(); });
})();
</script>

